package vn.deadline.tracker.web;
import jakarta.servlet.http.HttpServletRequest;import org.springframework.core.io.InputStreamResource;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.stereotype.Controller;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import vn.deadline.tracker.security.TrackerPrincipal;import vn.deadline.tracker.service.AttachmentService;import java.nio.charset.StandardCharsets;import java.util.*;
@Controller
public class AttachmentController {
 private final AttachmentService attachments;
 public AttachmentController(AttachmentService attachments){this.attachments=attachments;}
 @PostMapping("/groups/{group}/tasks/{task}/attachments") String upload(@PathVariable String group,@PathVariable String task,@RequestParam("file") List<MultipartFile> files,@RequestParam(required=false) String commentId,@AuthenticationPrincipal TrackerPrincipal actor){if(files==null||files.size()!=1)throw vn.deadline.tracker.domain.RuleViolation.invalid("Mỗi yêu cầu chỉ nhận một tệp.");try{attachments.upload(actor.id(),group,task,files.getFirst(),commentId);return "redirect:/groups/"+group+"/tasks/"+task;}catch(java.io.IOException e){throw new IllegalStateException("Attachment upload failed",e);}}
 @GetMapping("/groups/{group}/tasks/{task}/attachments/{id}") ResponseEntity<InputStreamResource> download(@PathVariable String group,@PathVariable String task,@PathVariable String id,@AuthenticationPrincipal TrackerPrincipal actor)throws java.io.IOException{
  var result=attachments.download(actor.id(),group,task,id);var meta=result.metadata();var disposition=ContentDisposition.attachment().filename(meta.displayName,StandardCharsets.UTF_8).build();
  return ResponseEntity.ok().contentType(MediaType.parseMediaType(meta.mediaType)).contentLength(meta.sizeBytes).header(HttpHeaders.CONTENT_DISPOSITION,disposition.toString()).header("X-Content-Type-Options","nosniff").body(new InputStreamResource(result.body()));
 }
 @PostMapping("/groups/{group}/tasks/{task}/attachments/{id}/hide") String hide(@PathVariable String group,@PathVariable String task,@PathVariable String id,@AuthenticationPrincipal TrackerPrincipal actor){attachments.hide(actor.id(),group,task,id);return "redirect:/groups/"+group+"/tasks/"+task;}
 @PostMapping("/groups/{group}/tasks/{task}/pins/{kind}/{id}") String pin(@PathVariable String group,@PathVariable String task,@PathVariable String kind,@PathVariable String id,@AuthenticationPrincipal TrackerPrincipal actor){boolean file="attachment".equals(kind);if(!file&& !"comment".equals(kind))throw vn.deadline.tracker.domain.RuleViolation.missing();attachments.pin(actor.id(),group,task,id,file);return "redirect:/groups/"+group+"/tasks/"+task;}
 @PostMapping("/groups/{group}/tasks/{task}/pins/{kind}/{id}/remove") String unpin(@PathVariable String group,@PathVariable String task,@PathVariable String kind,@PathVariable String id,@AuthenticationPrincipal TrackerPrincipal actor){boolean file="attachment".equals(kind);if(!file&& !"comment".equals(kind))throw vn.deadline.tracker.domain.RuleViolation.missing();attachments.unpin(actor.id(),group,task,id,file);return "redirect:/groups/"+group+"/tasks/"+task;}
}
